/* Shared temporal controls use Hugeicons; native inputs retain typing and validation. */
let temporalPicker=null;
function enhanceTemporalFields(){for(const input of document.querySelectorAll('input[type="date"],input[type="time"],input[type="month"]')){
  if(input.parentElement.classList.contains('temporal-field'))continue;
  const wrap=document.createElement('span');wrap.className='temporal-field temporal-'+input.type;
  input.before(wrap);wrap.append(input);
  const button=document.createElement('button');button.type='button';button.className='temporal-trigger';button.disabled=input.disabled;
  const name=input.getAttribute('aria-label')||input.name?.replace(/([A-Z])/g,' $1').toLowerCase()||input.type;
  button.setAttribute('aria-label','Choose '+name);button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');
  button.innerHTML=icon(input.type==='time'?'clock':'calendar');button.onclick=event=>{event.preventDefault();openTemporalPicker(input,button)};wrap.append(button);
}}
function closeTemporalPicker(){if(temporalPicker)temporalPicker.button.setAttribute('aria-expanded','false');document.querySelector('.temporal-popover')?.remove();temporalPicker=null}
function openTemporalPicker(input,button){if(temporalPicker?.input===input){closeTemporalPicker();return}closeTemporalPicker();const date=input.value&&input.type!=='time'?new Date(input.value+(input.type==='month'?'-01':'')+'T12:00:00'):new Date();temporalPicker={input,button,type:input.type,year:date.getFullYear(),month:date.getMonth()};button.setAttribute('aria-expanded','true');renderTemporalPicker()}
function temporalMonthStep(step){if(!temporalPicker)return;let p=temporalPicker;if(p.type==='month')p.year+=step;else{let date=new Date(p.year,p.month+step,1);p.year=date.getFullYear();p.month=date.getMonth()}renderTemporalPicker()}
function temporalDate(year,month,day){return year+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0')}
function renderTemporalPicker(){if(!temporalPicker)return;document.querySelector('.temporal-popover')?.remove();let p=temporalPicker,el=document.createElement('section');el.className='temporal-popover';el.setAttribute('role','dialog');el.setAttribute('aria-label',p.type==='time'?'Choose time':p.type==='month'?'Choose month':'Choose date');
 const nav=`<div class="temporal-picker-heading"><button type="button" aria-label="Previous ${p.type==='month'?'year':'month'}" onclick="temporalMonthStep(-1)">${icon('left')}</button><strong>${p.type==='month'?p.year:new Date(p.year,p.month,1).toLocaleDateString('en',{month:'long',year:'numeric'})}</strong><button type="button" aria-label="Next ${p.type==='month'?'year':'month'}" onclick="temporalMonthStep(1)">${icon('right')}</button></div>`;
 if(p.type==='date'){const offset=(new Date(p.year,p.month,1).getDay()+6)%7,total=new Date(p.year,p.month+1,0).getDate(),count=Math.ceil((offset+total)/7)*7;el.innerHTML=nav+`<div class="temporal-days">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>'<small>'+d+'</small>').join('')}${Array.from({length:count},(_,i)=>{const d=new Date(p.year,p.month,i-offset+1),value=temporalDate(d.getFullYear(),d.getMonth(),d.getDate()),disabled=(p.input.min&&value<p.input.min)||(p.input.max&&value>p.input.max);return `<button type="button" data-date="${value}" aria-label="${d.toLocaleDateString('en',{day:'numeric',month:'long',year:'numeric'})}" aria-pressed="${value===p.input.value}" class="${d.getMonth()!==p.month?'outside ':''}${value===p.input.value?'selected':''}" ${disabled?'disabled':''} onclick="setTemporalValue('${value}')">${d.getDate()}</button>`}).join('')}</div><footer><button type="button" onclick="setTemporalValue('')">${icon('close')} Clear</button><button type="button" onclick="temporalToday()">${icon('calendar')} Today</button></footer>`}
 else if(p.type==='month'){el.innerHTML=nav+`<div class="temporal-months">${Array.from({length:12},(_,month)=>{const value=p.year+'-'+String(month+1).padStart(2,'0');return `<button type="button" class="${value===p.input.value?'selected':''}" onclick="setTemporalValue('${value}')">${new Date(p.year,month,1).toLocaleDateString('en',{month:'short'})}</button>`}).join('')}</div><footer><button type="button" onclick="setTemporalValue('')">${icon('close')} Clear</button><button type="button" onclick="temporalToday()">${icon('calendar')} This month</button></footer>`}
 else{const [hour=11,minute=0]=(p.input.value||'11:00').split(':').map(Number);el.innerHTML=`<div class="temporal-picker-heading"><strong>${icon('clock')} Select time</strong><button type="button" aria-label="Close time picker" onclick="closeTemporalPicker()">${icon('close')}</button></div><div class="temporal-time-options"><label>Hour<select id="picker-hour">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${(hour%12||12)===i+1?'selected':''}>${String(i+1).padStart(2,'0')}</option>`).join('')}</select></label><span>:</span><label>Minute<select id="picker-minute">${Array.from({length:60},(_,i)=>`<option value="${i}" ${minute===i?'selected':''}>${String(i).padStart(2,'0')}</option>`).join('')}</select></label><label>Period<select id="picker-period"><option ${hour<12?'selected':''}>AM</option><option ${hour>=12?'selected':''}>PM</option></select></label></div><footer><button type="button" onclick="setTemporalValue('')">${icon('close')} Clear</button><button type="button" class="primary" onclick="applyTemporalTime()">${icon('tick')} Apply</button></footer>`}
 document.body.append(el);const rect=p.button.parentElement.getBoundingClientRect();el.style.left=Math.max(8,Math.min(rect.left,innerWidth-el.offsetWidth-8))+'px';el.style.top=(rect.bottom+el.offsetHeight+8>innerHeight?Math.max(8,rect.top-el.offsetHeight-6):rect.bottom+6)+'px';
}
function setTemporalValue(value){if(!temporalPicker)return;const input=temporalPicker.input;closeTemporalPicker();input.value=value;input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));if(input.isConnected)input.focus()}
function temporalToday(){const d=new Date(),value=temporalDate(d.getFullYear(),d.getMonth(),d.getDate());setTemporalValue(temporalPicker.type==='month'?value.slice(0,7):value)}
function applyTemporalTime(){const hour=+document.getElementById('picker-hour').value%12+(document.getElementById('picker-period').value==='PM'?12:0),minute=+document.getElementById('picker-minute').value;setTemporalValue(String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0'))}
const temporalObserver=new MutationObserver(enhanceTemporalFields);temporalObserver.observe(document.getElementById('app'),{childList:true,subtree:true});enhanceTemporalFields();
document.addEventListener('click',event=>{if(temporalPicker&&!event.target.closest('.temporal-popover')&&!event.target.closest('.temporal-trigger'))closeTemporalPicker()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&temporalPicker){const button=temporalPicker.button;closeTemporalPicker();button.focus()}});
window.addEventListener('resize',closeTemporalPicker);document.addEventListener('scroll',event=>{if(temporalPicker&&!event.target?.closest?.('.temporal-popover'))closeTemporalPicker()},true);
